    result = []
    i = 0
    while i < len(text):
        if text[i] == "\\" and i + 1 < len(text) and text[i + 1] in ASCII_PUNCTUATION:
            result.append(text[i + 1])
            i += 2
            continue
        result.append(text[i])
        i += 1
    return "".join(result)


