    match = re.search(r"(?:^|[ \t])#+$", text)
    if match:
        text = text[: match.start()]
    return text.strip()


_PARSER = MarkdownIt("commonmark").enable("table")


def parse(text: str) -> Document:
    lines = text.replace("\r\n", "\n").replace("\r", "\n").split("\n")
    if lines and lines[-1] == "":
        lines.pop()
